#!/usr/bin/env python3
"""Offline prototype of the monokl model-eval harness: tool-use loop, sandboxed command runner, deterministic grader and
cost accounting, driven by a FAKE model. No network, no API client, no key. Run: python3 -I proto.py"""
import json, os, re, shutil, subprocess, tempfile, time
from pathlib import Path

# $ per million tokens (platform.claude.com pricing page, 2026-11-23). Haiku 5.5 is the <=100K-prompt tier.
PRICES = {"claude-haiku-5-5": (0.10, 0.50), "claude-sonnet-5-5": (2.00, 10.00), "claude-opus-5-5": (4.00, 20.00)}
ALLOW = {"A": ["rg", "ls", "cat", "head", "tail", "wc", "sed"], "B": ["rg", "ls", "cat", "head", "tail", "wc", "sed", "monokl"]}
TURN_CAP, OUT_CAP = 8, 16_000  # tool calls per trial; bytes of one tool result


def cost(usage, model):
    """List price with no cache discount, so a lucky cache hit cannot bias an arm."""
    i, o = PRICES[model]
    raw_in = usage["input_tokens"] + usage.get("cache_read_input_tokens", 0) + usage.get("cache_creation_input_tokens", 0)
    return (raw_in * i + usage["output_tokens"] * o) / 1e6


def run_cmd(cmd, cwd, arm, bindir):
    for name in ALLOW[arm]:  # PATH holds only the allowed tools; a missing one is "command not found"
        p = shutil.which(name)
        if p and not (bindir / name).exists():
            (bindir / name).symlink_to(p)
    env = {"PATH": str(bindir), "HOME": "/nonexistent"}  # no API key, no inherited environment
    try:
        r = subprocess.run(["/bin/sh", "-c", cmd], cwd=cwd, env=env, capture_output=True, timeout=20)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = b"timeout after 20s", 124
    cut = max(len(out) - OUT_CAP, 0)
    text = out[:OUT_CAP].decode(errors="replace") + (f"\n[truncated {cut} bytes]" if cut else "")  # never silent
    return text, code, len(out)


def grade(answer, task, repo):
    """file exact, declaration line within 3 of a harness declaration line, signature text really on that line."""
    try:
        a = json.loads(answer.strip().splitlines()[-1])
        file, line, sig = a["file"].removeprefix("./"), int(a["line"]), a["signature"]
    except (ValueError, KeyError, TypeError, IndexError):
        return {"correct": False, "failure": "format_error"}
    if file not in task["files"]:
        return {"correct": False, "failure": "wrong_file"}
    lines = (repo / file).read_text().splitlines()
    near = [n for n in task["decl_lines"][file] if abs(n - line) <= 3]
    if not near:
        return {"correct": False, "failure": "right_file_wrong_line"}
    if not re.search(r"\b" + re.escape(task["symbol"]) + r"\b", sig):
        return {"correct": False, "failure": "wrong_symbol"}
    if " ".join(sig.split())[:40] not in " ".join(lines[near[0] - 1].split()):
        return {"correct": False, "failure": "ungrounded_signature"}
    return {"correct": True, "failure": None}


def run_trial(model_fn, model, arm, task, repo, spend):
    """model_fn(messages) -> (content blocks, usage). Returns one JSONL row."""
    bindir = Path(tempfile.mkdtemp())
    messages, calls, usage_total, t0 = [{"role": "user", "content": task["prompt"]}], [], {"input_tokens": 0, "output_tokens": 0}, time.time()
    answer, stop = "", "turn_cap"
    for _ in range(TURN_CAP + 1):  # the +1 is the final no-tool request
        blocks, usage = model_fn(messages)
        for k in usage_total:
            usage_total[k] += usage[k]
        spend[0] += cost(usage, model)
        messages.append({"role": "assistant", "content": blocks})
        tools = [b for b in blocks if b["type"] == "tool_use"]
        if not tools:
            answer, stop = "".join(b["text"] for b in blocks if b["type"] == "text"), "end_turn"
            break
        results = []
        for b in tools:
            text, code, raw = run_cmd(b["input"]["command"], repo, arm, bindir)
            calls.append({"cmd": b["input"]["command"], "exit": code, "bytes": raw, "tool": b["input"]["command"].split()[0]})
            results.append({"type": "tool_result", "tool_use_id": b["id"], "content": text})
        messages.append({"role": "user", "content": results})
    g = grade(answer, task, repo) if stop == "end_turn" else {"correct": False, "failure": "turn_cap"}
    return {"task": task["id"], "arm": arm, "model": model, "tool_calls": len(calls), "requests": len(calls) + (stop == "end_turn"),
            "usage": usage_total, "cost_usd": cost(usage_total, model), "wall_s": round(time.time() - t0, 3), **g, "calls": calls}


def toks(x):
    return -(-len(json.dumps(x)) // 3)  # ceil(bytes / 3), the product's estimate


def fake_model(symbol, wrong=False):
    def fn(messages):
        ctx = toks(messages)
        if len(messages) == 1:
            return [{"type": "tool_use", "id": "t1", "name": "bash", "input": {"command": f"rg -n -w {symbol}"}}], {"input_tokens": ctx, "output_tokens": 60}
        hit = messages[-1]["content"][0]["content"].splitlines()[0]
        f, n, text = hit.split(":", 2)
        ans = {"file": "nope.ts" if wrong else f, "line": int(n), "signature": text.strip()}
        return [{"type": "text", "text": json.dumps(ans)}], {"input_tokens": ctx, "output_tokens": 40}
    return fn


if __name__ == "__main__":
    repo = Path(tempfile.mkdtemp())
    (repo / "src").mkdir()
    (repo / "src/a.ts").write_text("// header\nexport function persist(x: number): number {\n  return x;\n}\n")
    task = {"id": "demo/ident/persist", "prompt": "Find where `persist` is declared.", "files": ["src/a.ts"], "symbol": "persist", "decl_lines": {"src/a.ts": [2]}}
    spend = [0.0]
    good = run_trial(fake_model("persist"), "claude-haiku-5-5", "A", task, repo, spend)
    bad = run_trial(fake_model("persist", wrong=True), "claude-haiku-5-5", "A", task, repo, spend)
    blocked = run_trial(fake_model("persist"), "claude-haiku-5-5", "A", task, repo, spend)  # same loop; monokl absent in arm A
    assert good["correct"] and good["failure"] is None, good
    assert not bad["correct"] and bad["failure"] == "wrong_file", bad
    # hand-checked: 1M in x $0.10 + 1M out x $0.50 = $0.60 for Haiku; Sonnet $12
    assert abs(cost({"input_tokens": 10**6, "output_tokens": 10**6}, "claude-haiku-5-5") - 0.60) < 1e-9
    assert abs(cost({"input_tokens": 10**6, "output_tokens": 10**6}, "claude-sonnet-5-5") - 12.0) < 1e-9
    r = run_cmd("monokl search x .; env; echo $ANTHROPIC_API_KEY", repo, "A", Path(tempfile.mkdtemp()))[0]
    assert "not found" in r and "ANTHROPIC" not in r, r
    print(json.dumps({"good": {k: good[k] for k in ("tool_calls", "requests", "usage", "cost_usd", "correct")}, "bad_failure": bad["failure"], "spend": round(spend[0], 8)}))
    print("proto ok")

